insert into public.grammar_points (pattern,meaning_id,meaning_en,structure,explanation_id,explanation_en,level,sort_order,is_published) values ('〜は〜です','adalah','is/am/are','N1 は N2 です','Pola dasar untuk menyatakan identitas atau keadaan.','Basic pattern for identity or state.','N5',1,true),('〜は〜ではありません','bukan','is not/am not','N1 は N2 ではありません','Bentuk negatif dari です.','Negative form of です.','N5',2,true),('〜ですか','apakah','is it?/are you?','N1 は N2 ですか','Digunakan untuk membuat pertanyaan.','Used to form questions.','N5',3,true),('これ・それ・あれ','ini/itu','this/that','これ/それ/あれ + noun','Kata tunjuk untuk benda.','Demonstratives for things.','N5',4,true),('〜をください','tolong beri','please give me','N を ください','Meminta sesuatu dengan sopan.','Polite request for an item.','N5',5,true),('〜を食べます','makan','eat','N を Vます','を menandai objek langsung.','を marks the direct object.','N5',6,true),('〜へ行きます','pergi ke','go to','Place へ 行きます','へ menunjukkan arah/tujuan.','へ marks direction or destination.','N5',7,true),('〜で〜ます','melakukan di/dengan','do at/by','Place で V','で menunjukkan tempat aktivitas atau alat.','で marks activity location or means.','N5',8,true),('〜があります','ada (benda)','there is','Place に N があります','Untuk benda mati.','Used for inanimate things.','N5',9,true),('〜がいます','ada (makhluk)','there is/are','Place に N がいます','Untuk manusia dan hewan.','Used for people and animals.','N5',10,true)
